# 76. Minimum Window Substring
# Hard
# Topics
# Companies
# Hint
# Given two strings s and t of lengths m and n respectively, return the minimum window
# substring
#  of s such that every character in t (including duplicates) is included in the window. If there is no such substring, return the empty string "".

# The testcases will be generated such that the answer is unique.


# Example 1:

# Input: s = "ADOBECODEBANC", t = "ABC"
# Output: "BANC"
# Explanation: The minimum window substring "BANC" includes 'A', 'B', and 'C' from string t.
# Example 2:

# Input: s = "a", t = "a"
# Output: "a"
# Explanation: The entire string s is the minimum window.
# Example 3:

# Input: s = "a", t = "aa"
# Output: ""
# Explanation: Both 'a's from t must be included in the window.
# Since the largest window of s only has one 'a', return empty string.


# Constraints:

# m == s.length
# n == t.length
# 1 <= m, n <= 105
# s and t consist of uppercase and lowercase English letters.


# Follow up: Could you find an algorithm that runs in O(m + n) time?


from collections import defaultdict


def minWindow(s: str, t: str) -> str:
    # s = "ADOBECODEBANC", t = "ABC"
    def hmap_check(hmap1, hmap2):
        for k, v in hmap1.items():
            if hmap2[k] < v:
                return False
        return True

    lp = 0
    window_size = len(t)
    rp = lp + window_size - 1

    hmap1 = defaultdict(lambda: 0)
    hmap2 = defaultdict(lambda: 0)

    for ch in t:
        hmap1[ch] += 1

    while window_size <= len(s):
        while rp - lp == window_size - 1 and rp < len(s):
            hmap2 = defaultdict(lambda: 0)

            for ch in s[lp : rp + 1]:
                hmap2[ch] += 1
            if hmap_check(hmap1, hmap2):
                return s[lp : rp + 1]
            else:
                lp += 1
                rp += 1
        window_size += 1
        lp = 0
        rp = lp + window_size - 1
    return ""


if __name__ == "__main__":
    print(minWindow("aaaaaaaaaaaabbbbbcdd", "abcdd"))
    print(minWindow("ADOBECODEBANC", "ABC"))
    print(minWindow("a", "a"))
    print(minWindow("a", "aa"))

    # Need to optimize the solution for this testcase
    print(
        minWindow(
            "",
            "",
        )
    )
